/bin/bash -lc "python3 - <<'PY'
import json,re
keys=['anderson2024comprehensive','kosir2022comparative','heywood2023tailoring','gullbrekken2025phase','zhang2024unveiling','feng2023discovery','zhang2023ultrafast','park2026li2co3','moy2025irreversible','garman2025reaction','nasir2025excess','golmohammad2024effects','ahmad2025reducing','li2026green','ali2021spray','saran2024optical','saran2025structural','qin2026influence','shi2025li2co3','zhang2023on','li2026structure','aote2024effect','giri2026entropy','klimpel2023standardizing']
# map key to DOI from bib
s=open('<HOME>').read(); entries=re.findall(r'@\\w+\\{(["'^,]+),(.*?)(?='"\\n@\\w+\\{|\\Z)',s,re.S)
D={};
for k,b in entries:
 if k in keys:
  m=re.search(r'doi\\s*=\\s*\\{(["'^}]*)'"\\}',b,re.S); D[k]=m.group(1).strip() if m else None
bydoi={d.get('doi'):d for d in map(json.loads,open('<HOME>'))}
bytitle={d.get('title',''):d for d in map(json.loads,open('<HOME>'))}
for k in keys:
 d=bydoi.get(D.get(k))
 if not d:
  # find title by key tokens
  d=next((x for x in bytitle.values() if x.get('doi')==D.get(k)),None)
 print('\\n###',k,D.get(k))
 if d:
  print(d['title']); print(d.get('abstract') or '[NO ABSTRACT]')
 else: print('NOT FOUND')
PY"

