import json,glob,os,re
base='<HOME>'
failed=[]
for p in sorted(glob.glob(base+'/experiment_*.json')):
 d=json.load(open(p));
 req=['process','precursors','safety','characterization','route_prediction','inorganic_model_status']
 miss=[k for k in req if not d.get(k)]
 phrase='演示数据，非化学结论'
 if phrase not in json.dumps(d,ensure_ascii=False): miss.append('stub_disclaimer')
 if len(d.get('route_prediction',{}).get('top5',[]))"'!=5: miss.append('"'top5')
 print(os.path.basename(p), 'PASS' if not miss else 'FAIL', miss)
 failed.extend((p,m) for m in miss)
for p in sorted(glob.glob(base+'/proposal_*.md')):
 s=open(p).read(); cites=set(re.findall(r'@([A-Za-z0-9_:-]+)',s));
 checks={'motivation':'## Motivation and gap evidence' in s,'method':'## Method sketch' in s,'validation':'## Validation plan' in s,'risk':'## Risks and alternatives' in s,'citations>=2':len(cites)>=2,'stub_label':'演示数据，非化学结论' in s}
 bad=[k for k,v in checks.items() if not v]; print(os.path.basename(p),'PASS' if not bad else 'FAIL',bad,'citations',len(cites)); failed.extend((p,m) for m in bad)
raise SystemExit(bool(failed))
PY"

